import {
  Group,
  PlaneGeometry,
  Mesh,
  MeshBasicNodeMaterial,
  TextureLoader,
  LinearFilter,
  ClampToEdgeWrapping
} from 'three/webgpu';

export default function createNode(config, ctx) {
  // Destructure config
  const {
    position = [0, 1, 0.06],
    rotation = [0, 0, 0],
    scale = [1, 1, 1],
    assets = {},
    textContent = [],
    colors = {},
    cinematicPrimitives = [],
    atlasRegion = { x: 0, y: 0, width: 512, height: 320 }
  } = config;

  // Main group
  const group = new Group();
  group.position.set(...position);
  group.rotation.set(...rotation);
  group.scale.set(...scale);

  // --- Background plane ---
  let bgMesh = null;
  if (assets.imageUrl) {
    const texture = ctx.textureLoader.load(assets.imageUrl);
    texture.minFilter = LinearFilter;
    texture.magFilter = LinearFilter;
    texture.wrapS = ClampToEdgeWrapping;
    texture.wrapT = ClampToEdgeWrapping;

    // Use atlas region to crop texture (assumes source rect is whole image for simplicity)
    // If atlas region is a sub-rect, adjust repeat/offset accordingly
    const imgWidth = 512; // fallback if texture image not yet loaded
    const imgHeight = 320;
    if (texture.image) {
      // If image loaded, use actual dimensions
      // For simplicity assume region exactly matches image
      texture.repeat.set(atlasRegion.width / texture.image.width, atlasRegion.height / texture.image.height);
      texture.offset.set(atlasRegion.x / texture.image.width, 1 - (atlasRegion.y + atlasRegion.height) / texture.image.height);
    } else {
      // Fallback repeat/offset
      texture.repeat.set(1, 1);
      texture.offset.set(0, 0);
    }

    // Geometry size based on aspect ratio
    const aspect = atlasRegion.width / atlasRegion.height;
    const planeWidth = 0.8; // scene units
    const planeHeight = planeWidth / aspect;
    const geometry = new PlaneGeometry(planeWidth, planeHeight);
    const material = new MeshBasicNodeMaterial({ map: texture });
    bgMesh = new Mesh(geometry, material);
    group.add(bgMesh);
  }

  // --- Text content ---
  const textObjects = [];
  if (ctx.fontAtlas && textContent.length > 0) {
    const roleToSize = {
      hero: 0.62,
      headline: 0.34,
      subhead: 0.2,
      body: 0.13,
      caption: 0.09
    };

    textContent.forEach((textItem) => {
      const {
        value = '',
        role = 'headline',
        size: explicitSize = null,
        weight = 400,
        color = colors.ink || '#16161d'
      } = textItem;

      // Font size: prefer role-based, but explicit pixel size overrides if given
      const fontSize = explicitSize ? explicitSize : (roleToSize[role] || 0.34);

      // Create text via fontAtlas (assumed returns a mesh with text)
      const textOptions = {
        fontFamily: 'Lora',
        fontWeight: weight,
        fontSize: fontSize,
        color: color
      };
      const textMesh = ctx.fontAtlas.createText(value, textOptions);
      if (textMesh) {
        // Position text in front of background
        textMesh.position.z = 0.01;
        // Center horizontally on background
        if (bgMesh) {
          textMesh.position.x = 0;
          textMesh.position.y = 0;
        }
        group.add(textMesh);
        textObjects.push(textMesh);
      }
    });
  }

  // --- Cinematic primitives (none in this spec) ---
  cinematicPrimitives.forEach((prim) => {
    ctx.primitives[prim.name](group, prim.params);
  });

  // --- Handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Dispose background mesh
    if (bgMesh) {
      bgMesh.geometry.dispose();
      if (bgMesh.material.map) bgMesh.material.map.dispose();
      bgMesh.material.dispose();
    }
    // Dispose text meshes
    textObjects.forEach((mesh) => {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) {
        if (mesh.material.map) mesh.material.map.dispose();
        mesh.material.dispose();
      }
    });
    // Kill any GSAP timelines (none)
  };

  return group;
}
